#!/usr/bin/env python3
"""Full-screen scene art (AI-generated by the team, 1920×1080) -> public/img/<name>.jpg,
<name>.webp and <name>-sm.webp (800 px, phones), all with the AI-disclosure label burned in
(Space Apps rule for AI images). Used for:
  briefing.png -> briefing.*  ("Misión Lunar – Fase 1" briefing, components/map/Briefing.tsx)
  scene03.png  -> scene03.*   ("La Luna en Peligro": last Journey scene + boss intro, MoonScene.tsx)

The label uses the same text and style as scripts/extract_assets.py (small semi-transparent white
text with a faint outline, no box), centred at PLACEMENT[name] along the bottom edge, in a strip
that none of the HTML panels drawn over the art covers. The .jpg also gets the label as a JPEG
comment.

Requires Pillow (pip install Pillow). Always run it on the clean original PNG.

Usage:
  python scripts/make_scene_art.py ../briefing.png
  python scripts/make_scene_art.py ../scene03.png
  python scripts/make_scene_art.py <png> --out public/img   (output name = the PNG's file name)
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

from extract_assets import REPO_ROOT, SMALL_WIDTH, WEBP_QUALITY, WM_FILL, WM_STROKE, WM_TEXT, load_font

JPEG_QUALITY = 84
# Label geometry as fractions of the image width: font size, bottom margin, and the centre x per image.
WM_FONT = 0.0088
WM_BOTTOM = 0.0016
PLACEMENT = {
    # free strip under the bottom bar: x ≈ 31%–82%, bottom ~2.5% of the height
    "briefing": 0.5635,
    # between "Tutorial STEM" (ends x ≈ 17%) and "¡Continuar!" (starts x ≈ 81%), under Orbi's dialogue
    "scene03": 0.43,
}


def burn(src, cx: float):
    from PIL import Image, ImageDraw

    w, h = src.size
    size = max(10, round(WM_FONT * w))
    font = load_font(size)
    stroke = max(1, round(size / 14))
    l, t, r, b = font.getbbox(WM_TEXT, stroke_width=stroke)
    x0 = round(cx * w - (r - l) / 2)
    y0 = h - round(WM_BOTTOM * w) - (b - t)
    overlay = Image.new("RGBA", src.size, (0, 0, 0, 0))
    ImageDraw.Draw(overlay).text((x0 - l, y0 - t), WM_TEXT, font=font, fill=WM_FILL, stroke_width=stroke, stroke_fill=WM_STROKE)
    return Image.alpha_composite(src.convert("RGBA"), overlay).convert("RGB")


def main() -> int:
    from PIL import Image

    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("png", type=Path, help="Path to the clean original PNG (briefing.png, scene03.png)")
    parser.add_argument("--out", type=Path, default=REPO_ROOT / "public" / "img", help="Output directory (default: <repo>/public/img)")
    args = parser.parse_args()
    if not args.png.is_file():
        print(f"error: file not found: {args.png}", file=sys.stderr)
        return 1

    name = args.png.stem
    if name not in PLACEMENT:
        print(f"error: no label placement for {name!r} (add it to PLACEMENT)", file=sys.stderr)
        return 1
    img = burn(Image.open(args.png), PLACEMENT[name])
    args.out.mkdir(parents=True, exist_ok=True)
    jpg = args.out / f"{name}.jpg"
    img.save(jpg, "JPEG", quality=JPEG_QUALITY, optimize=True, progressive=True, comment=WM_TEXT.encode("utf-8"))
    webp = args.out / f"{name}.webp"
    img.save(webp, "WEBP", quality=WEBP_QUALITY, method=6)
    sm = args.out / f"{name}-sm.webp"
    img.resize((SMALL_WIDTH, round(img.height * SMALL_WIDTH / img.width)), Image.LANCZOS).save(sm, "WEBP", quality=WEBP_QUALITY, method=6)
    for p in (jpg, webp, sm):
        print(f"-> {p} ({p.stat().st_size:,} bytes)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
